/* Official user-selected second illustration: 星辰破印_金鏈環繞的魔法卡.png.
 * Bundled at card-photo size so it works offline and copies into unique local cards.
 * The original full-resolution image is never stored in players' localStorage. */
(function(root,factory){
 const art=factory();
 if(typeof module==='object'&&module.exports)module.exports=art;
 else root.LivingUnbindCardArt=art;
})(typeof self!=='undefined'?self:globalThis,function(){
 'use strict';
 return Object.freeze({
  id:'unbind-contract-user-selected-art-v1',
  image:Object.freeze({
   dataUrl:'data:image/jpeg;base64,',
   scale:1,x:50,y:50
  })
 });
});